#!/usr/bin/env python3
"""Step 2 协调器：引导 agent/人工逐条回填 results.json，并串联校验与出报告。

支持两种模式：
1. 传统人工/agent 回填（status / next / done / validate / report）
2. 自动模式（auto / auto-row）

自动模式当前定位：
- Part 1：用确定性规则从 spec_text / pdf_text 自动抽取并比较尺寸
- Part 2：通过独立接口脚本尝试视觉判定；未接入视觉模型时返回稳定失败结构
- 若未来接入视觉模型 / OCR，可沿用当前输入输出契约继续扩展

用法：
  python3 scripts/fill_results.py status
  python3 scripts/fill_results.py next
  python3 scripts/fill_results.py done <seq>
  python3 scripts/fill_results.py validate
  python3 scripts/fill_results.py report
  python3 scripts/fill_results.py auto [--part1-only] [--include-done]
  python3 scripts/fill_results.py auto-row <seq> [--part1-only]

约定：
- results.json 默认路径为 prepared/results.json
- “已完成”定义为：part1.verdict 与 part2.verdict 均非空
- 自动模式默认不会覆盖已完成 verdict；传 --include-done 才会重算
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable

RESULTS_PATH = Path("prepared/results.json")
VALIDATE_SCRIPT = Path("scripts/validate_results.py")
WRITE_REPORT_SCRIPT = Path("scripts/write_report.py")
VISION_ROW_SCRIPT = Path("scripts/vision_row.py")

PART1_ALLOWED = {"一致", "一致(顺序不同)", "不一致", "PDF未找到尺寸", "Excel未找到尺寸", "异常"}
PART2_ALLOWED = {"一致", "一致(顺序不同)", "不一致", "图示无法识别"}

LABEL_PRIORITY = [
    "纸箱制作尺寸",
    "制作尺寸",
    "外箱尺寸",
    "外箱大小",
    "纸箱尺寸",
    "纸箱大小",
    "成品尺寸",
    "成品大小",
]
MEAS_KEYWORDS = ["MEAS", "MEASUREMENT"]
HISTORY_KEYWORDS = [
    "由", "原", "原本", "原来", "原先", "原版", "原尺寸", "原规格",
    "旧", "旧版", "旧尺寸", "旧规格",
    "老", "老版本", "老规格",
    "之前", "以前", "过去", "修改前", "调整前", "变更前", "更改前", "修订前", "历史", "上一版", "上版",
    "old", "original", "previous", "was",
]
TRIPLE_RE = re.compile(
    r"(?P<a>\d+(?:\.\d+)?)\s*[x×*＊]\s*(?P<b>\d+(?:\.\d+)?)\s*[x×*＊]\s*(?P<c>\d+(?:\.\d+)?)\s*(?P<unit>mm|cm)?",
    re.IGNORECASE,
)
SINGLE_DIM_RE = re.compile(r"(?P<value>\d+(?:\.\d+)?)\s*(?P<unit>mm|cm)", re.IGNORECASE)


@dataclass
class Candidate:
    dims_mm: list[int]
    label: str = ""
    source: str = ""
    line_no: int | None = None
    text: str = ""
    score: int = 0


@dataclass
class AutoFillResult:
    seq: str
    part1_changed: bool = False
    part2_changed: bool = False
    skipped: bool = False
    message: str = ""


def load_results() -> dict:
    if not RESULTS_PATH.exists():
        raise RuntimeError(f"results.json 不存在: {RESULTS_PATH}")
    return json.loads(RESULTS_PATH.read_text(encoding="utf-8"))


def save_results(data: dict) -> None:
    RESULTS_PATH.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def is_done(row: dict) -> bool:
    if row.get("match_status") != "ok":
        return True
    p1 = row.get("part1") or {}
    p2 = row.get("part2") or {}
    return bool(p1.get("verdict")) and bool(p2.get("verdict"))


def pending_rows(data: dict) -> list[dict]:
    return [row for row in data.get("rows", []) if row.get("match_status") == "ok" and not is_done(row)]


def print_status(data: dict) -> int:
    rows = data.get("rows", [])
    ok_rows = [r for r in rows if r.get("match_status") == "ok"]
    done_rows = [r for r in ok_rows if is_done(r)]
    print(f"results: {RESULTS_PATH}")
    print(f"总行数: {len(rows)}")
    print(f"ok 行: {len(ok_rows)}")
    print(f"已完成: {len(done_rows)}")
    print(f"待完成: {len(ok_rows) - len(done_rows)}")
    return 0


def print_next(data: dict) -> int:
    pendings = pending_rows(data)
    if not pendings:
        print("所有 ok 行都已填写完成。")
        return 0

    row = pendings[0]
    print("请处理下一条记录：")
    print(f"- seq: {row.get('seq')}")
    print(f"- material_code: {row.get('material_code')}")
    print(f"- model_code: {row.get('model_code')}")
    print(f"- spec_text: {row.get('spec_text')}")
    print(f"- pdf_filename: {row.get('pdf_filename')}")
    print(f"- pdf_image_path: {row.get('pdf_image_path')}")
    print("- 需要填写: part1 / part2")
    print("- 自动尝试: python3 scripts/fill_results.py auto-row <seq>")
    print("- 完成后可用命令: python3 scripts/fill_results.py done <seq>")
    return 0


def mark_done(data: dict, seq: str) -> int:
    rows = data.get("rows", [])
    matches = [r for r in rows if str(r.get("seq")) == str(seq)]
    if not matches:
        print(f"未找到 seq={seq} 的记录", file=sys.stderr)
        return 1

    target = matches[0]
    p1 = target.get("part1") or {}
    p2 = target.get("part2") or {}
    if not p1.get("verdict") or not p2.get("verdict"):
        print(f"seq={seq} 尚未填写完整，不能标记完成", file=sys.stderr)
        return 1

    target["step2_done"] = True
    save_results(data)
    print(f"已标记完成: seq={seq}")
    return 0


def run_validate() -> int:
    return subprocess.run([sys.executable, str(VALIDATE_SCRIPT), str(RESULTS_PATH)]).returncode


def run_report() -> int:
    rc = run_validate()
    if rc != 0:
        print("校验未通过，已阻止生成报告", file=sys.stderr)
        return rc
    return subprocess.run([sys.executable, str(WRITE_REPORT_SCRIPT), str(RESULTS_PATH)]).returncode


def _normalize_spaces(text: str) -> str:
    return " ".join((text or "").replace("\u00a0", " ").split())


def _mm_from_value(value: str, unit: str | None, default_unit: str = "mm") -> int | None:
    unit = (unit or default_unit or "mm").lower()
    number = float(value)
    mm = number * 10 if unit == "cm" else number
    rounded = round(mm)
    if abs(mm - rounded) > 1e-9:
        return None
    return int(rounded)


def _parse_triples(text: str, default_unit: str = "mm") -> list[list[int]]:
    triples: list[list[int]] = []
    for match in TRIPLE_RE.finditer(text or ""):
        dims = []
        for key in ("a", "b", "c"):
            mm = _mm_from_value(match.group(key), match.group("unit"), default_unit=default_unit)
            if mm is None:
                dims = []
                break
            dims.append(mm)
        if dims:
            triples.append(dims)
    return triples


def _parse_excel_dims(spec_text: str) -> tuple[list[int], str | None]:
    triples = _parse_triples(spec_text or "", default_unit="cm")
    if not triples:
        return [], "Excel 规格未解析出三元组"
    return triples[0], None


def _contains_any(text: str, keywords: Iterable[str]) -> bool:
    upper = (text or "").upper()
    lower = (text or "").lower()
    for kw in keywords:
        if kw.upper() in upper or kw.lower() in lower:
            return True
    return False


def _candidate_score(line: str, label: str, dims: list[int]) -> int:
    score = 0
    if label:
        score += 1000 - LABEL_PRIORITY.index(label) * 100
    if "改为" in line or "变更" in line:
        score += 80
    if len(set(dims)) == 3:
        score += 3
    return score


def _extract_pdf_candidates(pdf_text: str) -> list[Candidate]:
    candidates: list[Candidate] = []
    lines = (pdf_text or "").splitlines()
    for idx, raw_line in enumerate(lines, start=1):
        line = _normalize_spaces(raw_line)
        if not line:
            continue
        if _contains_any(line, MEAS_KEYWORDS):
            continue

        labels = [label for label in LABEL_PRIORITY if label in line]
        line_triples = _parse_triples(line, default_unit="mm")

        for label in labels:
            for dims in line_triples:
                candidates.append(Candidate(
                    dims_mm=dims,
                    label=label,
                    source="labelled",
                    line_no=idx,
                    text=line,
                    score=_candidate_score(line, label, dims),
                ))

        if "改为" in line:
            tail = line.split("改为", 1)[1]
            for dims in _parse_triples(tail, default_unit="mm"):
                candidates.append(Candidate(
                    dims_mm=dims,
                    label=labels[0] if labels else "",
                    source="change_tail",
                    line_no=idx,
                    text=line,
                    score=_candidate_score(line, labels[0] if labels else "", dims) + 50,
                ))

    deduped: dict[tuple[tuple[int, ...], str, int | None], Candidate] = {}
    for cand in candidates:
        key = (tuple(cand.dims_mm), cand.label, cand.line_no)
        if key not in deduped or cand.score > deduped[key].score:
            deduped[key] = cand

    return sorted(deduped.values(), key=lambda c: (-c.score, c.line_no or 0, c.dims_mm))


def _compare_dims(excel_dims: list[int], other_dims: list[int]) -> str:
    if excel_dims == other_dims:
        return "一致"
    if sorted(excel_dims) == sorted(other_dims):
        return "一致(顺序不同)"
    return "不一致"


def build_part1(row: dict) -> dict:
    spec_text = row.get("spec_text", "")
    pdf_text = row.get("pdf_text", "")
    pdf_filename = row.get("pdf_filename", "") or ""
    material_code = str(row.get("material_code", "") or "")

    excel_dims, excel_err = _parse_excel_dims(spec_text)
    filename_contains = material_code in pdf_filename if material_code else False

    if excel_err:
        return {
            "filename_contains_material_code": filename_contains,
            "excel_dimensions_mm": [],
            "pdf_dimensions_mm": [],
            "pdf_label_used": "",
            "pdf_other_dimensions_mm": [],
            "verdict": "Excel未找到尺寸",
            "reasoning": excel_err,
            "auto_source": "rule-based-text",
        }

    candidates = _extract_pdf_candidates(pdf_text)
    if not candidates:
        return {
            "filename_contains_material_code": filename_contains,
            "excel_dimensions_mm": excel_dims,
            "pdf_dimensions_mm": [],
            "pdf_label_used": "",
            "pdf_other_dimensions_mm": [],
            "verdict": "PDF未找到尺寸",
            "reasoning": "PDF 文本未找到符合规则的带标签尺寸三元组",
            "auto_source": "rule-based-text",
        }

    chosen = candidates[0]
    others = [cand.dims_mm for cand in candidates[1:]]
    verdict = _compare_dims(excel_dims, chosen.dims_mm)
    reason = f"Excel {excel_dims[0]}×{excel_dims[1]}×{excel_dims[2]}mm；PDF"
    if chosen.line_no:
        reason += f" 第{chosen.line_no}行"
    if chosen.label:
        reason += f"“{chosen.label}”"
    reason += f" 提取 {chosen.dims_mm[0]}×{chosen.dims_mm[1]}×{chosen.dims_mm[2]}mm"

    return {
        "filename_contains_material_code": filename_contains,
        "excel_dimensions_mm": excel_dims,
        "pdf_dimensions_mm": chosen.dims_mm,
        "pdf_label_used": chosen.label,
        "pdf_other_dimensions_mm": others,
        "verdict": verdict,
        "reasoning": reason[:200],
        "auto_source": "rule-based-text",
    }


def build_part2_placeholder(row: dict, part1: dict | None = None) -> dict:
    image_path = row.get("pdf_image_path", "") or ""
    excel_dims, excel_err = _parse_excel_dims(row.get("spec_text", ""))
    note = "自动模式视觉判定未成功，已回退为稳定失败结构"
    if image_path:
        note += f"；待处理图片: {image_path}"
    if excel_err:
        note += "；且 Excel 规格也未成功解析"
    elif part1 and part1.get("pdf_dimensions_mm"):
        note += f"；文本侧候选为 {part1.get('pdf_dimensions_mm')}，但未作为视觉结论写死"

    return {
        "diagram_dimensions_mm": [],
        "verdict": "图示无法识别",
        "reasoning": note[:200],
        "auto_source": "vision-fallback",
        "needs_manual_review": True,
    }


def _run_part2(row: dict, part1: dict | None = None) -> dict:
    seq = str(row.get("seq", ""))
    try:
        proc = subprocess.run(
            [sys.executable, str(VISION_ROW_SCRIPT), seq],
            check=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        if proc.returncode != 0:
            return build_part2_placeholder(row, part1)
        payload = json.loads(proc.stdout.strip())
        if not isinstance(payload, dict):
            return build_part2_placeholder(row, part1)
        return payload
    except Exception:
        return build_part2_placeholder(row, part1)


def _ensure_part_contract(part1: dict, part2: dict) -> None:
    if part1.get("verdict") not in PART1_ALLOWED:
        raise RuntimeError(f"part1 verdict 非法: {part1.get('verdict')!r}")
    if part2.get("verdict") not in PART2_ALLOWED:
        raise RuntimeError(f"part2 verdict 非法: {part2.get('verdict')!r}")


def auto_fill_row(row: dict, *, part1_only: bool = False, force: bool = False) -> AutoFillResult:
    result = AutoFillResult(seq=str(row.get("seq", "")))
    if row.get("match_status") != "ok":
        result.skipped = True
        result.message = f"skip: match_status={row.get('match_status')}"
        return result

    row.setdefault("part1", {})
    row.setdefault("part2", {})

    part1_existing = row.get("part1") or {}
    part2_existing = row.get("part2") or {}

    try:
        if force or not part1_existing.get("verdict"):
            row["part1"] = build_part1(row)
            result.part1_changed = True

        if not part1_only and (force or not part2_existing.get("verdict")):
            row["part2"] = _run_part2(row, row.get("part1"))
            result.part2_changed = True

        _ensure_part_contract(row.get("part1") or {}, row.get("part2") or build_part2_placeholder(row, row.get("part1")))
        row["step2_done"] = bool((row.get("part1") or {}).get("verdict")) and bool((row.get("part2") or {}).get("verdict"))
        result.message = "ok"
    except Exception as exc:
        row.setdefault("part1", part1_existing)
        row.setdefault("part2", part2_existing)
        result.message = f"failed: {exc}"
        raise

    return result


def run_auto(data: dict, *, target_seq: str | None = None, part1_only: bool = False, include_done: bool = False) -> int:
    rows = data.get("rows", [])
    touched = 0
    scanned = 0

    for row in rows:
        if target_seq is not None and str(row.get("seq")) != str(target_seq):
            continue
        scanned += 1
        if row.get("match_status") != "ok":
            continue
        if not include_done and is_done(row):
            continue
        auto_fill_row(row, part1_only=part1_only, force=include_done)
        touched += 1

    if target_seq is not None and scanned == 0:
        print(f"未找到 seq={target_seq} 的记录", file=sys.stderr)
        return 1

    save_results(data)
    print(f"自动回填完成: touched={touched}")
    print(f"模式: {'part1-only' if part1_only else 'part1+part2占位'}")
    if not include_done:
        print("说明: 已完成行默认跳过；如需重算请传 --include-done")
    return 0


def main() -> int:
    if len(sys.argv) < 2:
        print(__doc__.strip())
        return 1

    cmd = sys.argv[1]
    data = load_results()

    if cmd == "status":
        return print_status(data)
    if cmd == "next":
        return print_next(data)
    if cmd == "done":
        if len(sys.argv) != 3:
            print("用法: python3 scripts/fill_results.py done <seq>", file=sys.stderr)
            return 1
        return mark_done(data, sys.argv[2])
    if cmd == "validate":
        return run_validate()
    if cmd == "report":
        return run_report()
    if cmd == "auto":
        part1_only = "--part1-only" in sys.argv[2:]
        include_done = "--include-done" in sys.argv[2:]
        return run_auto(data, part1_only=part1_only, include_done=include_done)
    if cmd == "auto-row":
        if len(sys.argv) < 3:
            print("用法: python3 scripts/fill_results.py auto-row <seq> [--part1-only]", file=sys.stderr)
            return 1
        seq = sys.argv[2]
        part1_only = "--part1-only" in sys.argv[3:]
        include_done = "--include-done" in sys.argv[3:]
        return run_auto(data, target_seq=seq, part1_only=part1_only, include_done=include_done)

    print(f"未知命令: {cmd}", file=sys.stderr)
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""校验 results.json 是否达到可出报告的最低要求。

用法：
  python3 scripts/validate_results.py [prepared/results.json]
"""

import json
import sys
from pathlib import Path

ALLOWED_PART1 = {"一致", "一致(顺序不同)", "不一致", "PDF未找到尺寸", "Excel未找到尺寸", "异常"}
ALLOWED_PART2 = {"一致", "一致(顺序不同)", "不一致", "图示无法识别"}


def _is_dims(value):
    return isinstance(value, list) and all(isinstance(x, int) for x in value)


def main() -> int:
    results_path = Path(sys.argv[1]) if len(sys.argv) >= 2 else Path("prepared/results.json")
    if not results_path.exists():
        print(f"错误: results.json 不存在: {results_path}", file=sys.stderr)
        return 1

    data = json.loads(results_path.read_text(encoding="utf-8"))
    errors = []

    for idx, row in enumerate(data.get("rows", []), start=1):
        if row.get("match_status") != "ok":
            continue

        part1 = row.get("part1")
        part2 = row.get("part2")
        row_id = f"第{idx}行(seq={row.get('seq')}, material_code={row.get('material_code')})"

        if not isinstance(part1, dict):
            errors.append(f"{row_id}: 缺少 part1")

        else:
            verdict = part1.get("verdict")
            if verdict not in ALLOWED_PART1:
                errors.append(f"{row_id}: part1.verdict 非法或为空 -> {verdict!r}")
            if part1.get("excel_dimensions_mm") and not _is_dims(part1.get("excel_dimensions_mm")):
                errors.append(f"{row_id}: part1.excel_dimensions_mm 不是整数列表")
            if part1.get("pdf_dimensions_mm") and not _is_dims(part1.get("pdf_dimensions_mm")):
                errors.append(f"{row_id}: part1.pdf_dimensions_mm 不是整数列表")
            if part1.get("pdf_other_dimensions_mm"):
                other = part1.get("pdf_other_dimensions_mm")
                if not isinstance(other, list) or any(not _is_dims(x) for x in other):
                    errors.append(f"{row_id}: part1.pdf_other_dimensions_mm 不是整数列表数组")

        if not isinstance(part2, dict):
            errors.append(f"{row_id}: 缺少 part2")
        else:
            verdict = part2.get("verdict")
            if verdict not in ALLOWED_PART2:
                errors.append(f"{row_id}: part2.verdict 非法或为空 -> {verdict!r}")
            if part2.get("diagram_dimensions_mm") and not _is_dims(part2.get("diagram_dimensions_mm")):
                errors.append(f"{row_id}: part2.diagram_dimensions_mm 不是整数列表")
            if "needs_manual_review" in part2 and not isinstance(part2.get("needs_manual_review"), bool):
                errors.append(f"{row_id}: part2.needs_manual_review 必须是布尔值")

    if errors:
        print("校验失败:")
        for err in errors:
            print(f"- {err}")
        return 1

    print(f"校验通过: {results_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

