#!/usr/bin/env python3
"""对单条记录执行视觉判定（Part 2）。

优先级：
1. 通过 OpenClaw CLI 的多模态能力做真实读图（如当前环境可用）
2. 若脚本层无法真正调起可用视觉模型，则返回工程化的稳定降级结构

说明：
- 这里接的是“脚本 -> OpenClaw CLI 推理能力”的桥接，不是直接调用聊天层 image 工具。
- 脚本会主动探测：CLI 是否存在、是否支持模型列举、是否有 image 输入模型、是否具备可用认证。
- 一旦桥接链路某一环失败，会把失败原因写进 reasoning / probe，避免伪装成“已接通”。

用法：
  python3 scripts/vision_row.py <seq>
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any

RESULTS_PATH = Path("prepared/results.json")
MAX_REASON_LEN = 200
DEFAULT_MODEL = os.environ.get("PO_PDF_VISION_MODEL", "azure-openai-responses/gpt-5.4")
TRIPLE_RE = re.compile(r"(\d+(?:\.\d+)?)\s*[x×*＊]\s*(\d+(?:\.\d+)?)\s*[x×*＊]\s*(\d+(?:\.\d+)?)\s*(mm|cm)?", re.IGNORECASE)
JSON_RE = re.compile(r"\{[\s\S]*\}")


def load_results() -> dict:
    if not RESULTS_PATH.exists():
        raise RuntimeError(f"results.json 不存在: {RESULTS_PATH}")
    return json.loads(RESULTS_PATH.read_text(encoding="utf-8"))


def fallback(reason: str, *, probe: dict[str, Any] | None = None) -> dict:
    payload = {
        "diagram_dimensions_mm": [],
        "verdict": "图示无法识别",
        "reasoning": reason[:MAX_REASON_LEN],
        "auto_source": "vision-fallback",
        "needs_manual_review": True,
    }
    if probe:
        payload["probe"] = probe
    return payload


def _run(cmd: list[str], timeout: int = 120) -> subprocess.CompletedProcess[str]:
    return subprocess.run(cmd, check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=timeout)


def _probe_openclaw(model: str) -> dict[str, Any]:
    probe: dict[str, Any] = {
        "bridge": "openclaw-infer-model-run",
        "requested_model": model,
        "cli_found": False,
        "model_list_ok": False,
        "model_supports_image": False,
        "auth_ok": False,
    }
    if not shutil_which("openclaw"):
        probe["error"] = "openclaw CLI 不存在"
        return probe
    probe["cli_found"] = True

    listed = _run(["openclaw", "infer", "model", "list"], timeout=120)
    combined = (listed.stdout or "") + "\n" + (listed.stderr or "")
    if listed.returncode == 0:
        probe["model_list_ok"] = True
        probe["model_supports_image"] = _model_has_image_input(combined, model)
    else:
        probe["list_error"] = combined[:500]

    test = _run([
        "openclaw", "infer", "model", "run",
        "--json",
        "--model", model,
        "--prompt", '{"probe":"vision-auth-check"}'
    ], timeout=120)
    t = (test.stdout or "") + "\n" + (test.stderr or "")
    if test.returncode == 0:
        probe["auth_ok"] = True
    elif "No API key found" in t or "Auth lookup failed" in t:
        probe["auth_ok"] = False
        probe["auth_error"] = t[:500]
    elif "input: [\"text\",\"image\"]" in combined or '"image"' in combined:
        probe["auth_ok"] = True
        probe["auth_probe_inconclusive"] = t[:500]
    else:
        probe["auth_probe_inconclusive"] = t[:500]
    return probe


def shutil_which(name: str) -> str | None:
    from shutil import which
    return which(name)


def _model_has_image_input(model_list_text: str, model: str) -> bool:
    needle = f'"id":"{model.split('/', 1)[-1]}"'
    if needle in model_list_text and '"image"' in model_list_text[model_list_text.find(needle): model_list_text.find('\n', model_list_text.find(needle)) + 400]:
        return True
    return model in model_list_text and '"image"' in model_list_text


def _extract_json(text: str) -> dict[str, Any] | None:
    if not text:
        return None
    text = text.strip()
    try:
        obj = json.loads(text)
        if isinstance(obj, dict):
            return obj
    except Exception:
        pass
    match = JSON_RE.search(text)
    if not match:
        return None
    try:
        obj = json.loads(match.group(0))
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None


def _to_mm(value: Any, unit: str | None) -> int | None:
    try:
        number = float(value)
    except Exception:
        return None
    unit = (unit or "mm").lower()
    mm = number * 10 if unit == "cm" else number
    rounded = round(mm)
    if abs(mm - rounded) > 1e-9:
        return None
    return int(rounded)


def _normalize_dims(obj: dict[str, Any]) -> list[int]:
    dims = obj.get("diagram_dimensions_mm")
    if isinstance(dims, list) and len(dims) == 3:
        out = []
        for x in dims:
            if not isinstance(x, int):
                return []
            out.append(x)
        return out
    reasoning = str(obj.get("reasoning") or "")
    m = TRIPLE_RE.search(reasoning)
    if not m:
        return []
    dims2 = [_to_mm(m.group(1), m.group(4)), _to_mm(m.group(2), m.group(4)), _to_mm(m.group(3), m.group(4))]
    if any(v is None for v in dims2):
        return []
    return [int(v) for v in dims2]


def _vision_prompt(row: dict) -> str:
    spec = row.get("spec_text", "") or ""
    return (
        "你是纸箱规格图视觉判定器。只做读图，不要编造。\n"
        f"Excel 目标规格原文（仅供你理解任务，不要据此反推图片数字）: {spec}\n"
        "规则：\n"
        "1) 只接受图示中明确标注的长宽高三元组；\n"
        "2) 接受 mm 或 cm，输出统一为整数 mm；\n"
        "3) 排除 MEAS/MEASUREMENT；\n"
        "4) 排除历史旧值，如‘由X改为Y’中的X；\n"
        "5) 若看不清或没有有效三元组，返回 JSON："
        '{"diagram_dimensions_mm":[],"verdict":"图示无法识别","reasoning":"..."}；\n'
        "6) 若能识别，只返回 JSON，verdict 先固定写‘不一致’，因为脚本稍后会按 Excel 自动改判；"
        '{"diagram_dimensions_mm":[a,b,c],"verdict":"不一致","reasoning":"图中识别到 ..."}\n'
        "禁止输出 JSON 以外的任何内容。"
    )


def _compare(excel_dims: list[int], diagram_dims: list[int]) -> str:
    if not excel_dims or not diagram_dims:
        return "图示无法识别"
    if excel_dims == diagram_dims:
        return "一致"
    if sorted(excel_dims) == sorted(diagram_dims):
        return "一致(顺序不同)"
    return "不一致"


def _parse_excel_dims(spec_text: str) -> list[int]:
    m = TRIPLE_RE.search(spec_text or "")
    if not m:
        return []
    unit = m.group(4) or "cm"
    dims = [_to_mm(m.group(1), unit), _to_mm(m.group(2), unit), _to_mm(m.group(3), unit)]
    if any(v is None for v in dims):
        return []
    return [int(v) for v in dims]


def try_openclaw_vision(row: dict, image_path: Path) -> dict:
    probe = _probe_openclaw(DEFAULT_MODEL)
    if not probe.get("cli_found"):
        return fallback("OpenClaw CLI 不存在，无法从脚本层桥接视觉能力", probe=probe)
    if not probe.get("model_list_ok"):
        return fallback("OpenClaw CLI 模型探测失败，无法确认视觉模型可用性", probe=probe)
    if not probe.get("model_supports_image"):
        return fallback(f"模型不支持图片输入: {DEFAULT_MODEL}", probe=probe)
    if not probe.get("auth_ok"):
        return fallback("脚本层桥接已实现，但当前子代理环境缺少可用视觉模型认证", probe=probe)

    prompt = _vision_prompt(row)
    proc = _run([
        "openclaw", "infer", "model", "run",
        "--json",
        "--model", DEFAULT_MODEL,
        "--file", str(image_path),
        "--prompt", prompt,
    ], timeout=180)
    combined = (proc.stdout or "") + "\n" + (proc.stderr or "")
    if proc.returncode != 0:
        probe["invoke_error"] = combined[:800]
        return fallback("视觉桥接调用失败", probe=probe)

    obj = _extract_json(proc.stdout) or _extract_json(combined)
    if not obj:
        probe["invoke_output"] = combined[:800]
        return fallback("视觉桥接返回非 JSON，无法稳定解析", probe=probe)

    dims = _normalize_dims(obj)
    if not dims:
        obj = {
            "diagram_dimensions_mm": [],
            "verdict": "图示无法识别",
            "reasoning": str(obj.get("reasoning") or "模型未返回可用三元组")[:MAX_REASON_LEN],
        }
    else:
        excel_dims = _parse_excel_dims(str(row.get("spec_text") or ""))
        obj["diagram_dimensions_mm"] = dims
        obj["verdict"] = _compare(excel_dims, dims)
        obj["reasoning"] = str(obj.get("reasoning") or f"图中识别到 {dims[0]}×{dims[1]}×{dims[2]}mm")[:MAX_REASON_LEN]

    obj["auto_source"] = "openclaw-cli-vision-bridge"
    obj["needs_manual_review"] = False if obj.get("diagram_dimensions_mm") else True
    obj["probe"] = probe
    return obj


def main() -> int:
    if len(sys.argv) != 2:
        print("用法: python3 scripts/vision_row.py <seq>", file=sys.stderr)
        return 1

    seq = sys.argv[1]
    data = load_results()
    rows = data.get("rows", [])
    row = next((r for r in rows if str(r.get("seq")) == str(seq)), None)
    if row is None:
        print(f"未找到 seq={seq} 的记录", file=sys.stderr)
        return 1

    image_path = row.get("pdf_image_path")
    if not image_path:
        print(json.dumps(fallback("缺少 pdf_image_path"), ensure_ascii=False))
        return 0

    path = Path(image_path)
    if not path.exists():
        print(json.dumps(fallback(f"图片不存在: {image_path}"), ensure_ascii=False))
        return 0

    result = try_openclaw_vision(row, path)
    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

